<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {Check,Columns3,History,Info,LoaderCircle,Plus,RefreshCw,Save,Trash2} from 'lucide-vue-next';
import type {GlobalFieldCatalog,GlobalFieldCatalogState,GlobalFieldDefinition,GlobalFieldProjectStatus,GlobalFieldSynchronizationResult} from '../../../../packages/shared/src/global-fields';
import {post,request} from '../api';
import {useAppStore} from '../stores/app';
import {watchCredentialContext} from '../access-context';
import {cloneGlobalFieldDraft} from '../global-field-draft';
import '../styles/field-management.css';

const app=useAppStore(),state=ref<GlobalFieldCatalogState>(),fields=ref<GlobalFieldDefinition[]>([]),selected=ref('split');
const loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),baseline=ref('');
const projects=ref<GlobalFieldProjectStatus[]>(),projectSelection=ref<string[]>([]),projectLoading=ref(false),syncResults=ref<GlobalFieldSynchronizationResult>();
const identities=ref<Array<{id:string;name:string}>>(),managerId=ref('');
const adding=ref(false),newId=ref(''),newName=ref(''),oldDraft=ref<GlobalFieldDefinition[]>();
type HistoryEntry=Pick<GlobalFieldCatalog,'revision'|'updatedAt'|'updatedBy'>&{fieldCount:number};
const history=ref<HistoryEntry[]>(),historical=ref<GlobalFieldCatalog>(),historyLoading=ref(false);
let generation=0;
const field=computed(()=>fields.value.find(item=>item.id===selected.value));
const dirty=computed(()=>!!baseline.value&&JSON.stringify(fields.value)!==baseline.value);
const semantics:Record<string,string>={split:'训练、调优和测试角色。不是分支，也不混入金标或回归。',quality:'标注质量。金标需要答案、依据和证据经过严格审核。',purposes:'多选用途。回归与冒烟可以同时勾选，不改变数据划分。',visibility:'访问要求。实际权限仍由私有项目、成员和发布包受众控制。'};
const draftKey=()=>`oxen-web:global-fields:${app.status?.identity?.id??'guest'}`;
function remember(){if(loading.value||!state.value?.canEdit)return;try{if(dirty.value)localStorage.setItem(draftKey(),JSON.stringify({revision:state.value.catalog.revision,fields:fields.value}));else if(!oldDraft.value)localStorage.removeItem(draftKey());}catch{/* Keep inputs in memory if storage is unavailable. */}}
function validDraft(value:unknown):value is GlobalFieldDefinition[]{return Array.isArray(value)&&value.length<=200&&new Set(value.map(field=>field?.id)).size===value.length&&value.every(field=>field&&typeof field.id==='string'&&typeof field.displayName==='string'&&typeof field.description==='string'&&['single','multi'].includes(field.type)&&Array.isArray(field.options)&&field.options.length<=200&&field.options.every((option:unknown)=>!!option&&typeof option==='object'&&['id','displayName','color'].every(key=>typeof (option as Record<string,unknown>)[key]==='string')));}
async function load(){const current=++generation;loading.value=true;error.value='';oldDraft.value=undefined;try{const result=await request<GlobalFieldCatalogState>('/global-fields');if(current!==generation)return;state.value=result;fields.value=structuredClone(result.catalog.fields);baseline.value=JSON.stringify(fields.value);if(result.canEdit)try{const text=localStorage.getItem(draftKey());if(text){const draft=JSON.parse(text);if(validDraft(draft.fields)){if(draft.revision===result.catalog.revision){fields.value=draft.fields;notice.value='已恢复此身份未保存的字段配置。';}else{oldDraft.value=draft.fields;notice.value='全局目录已变化，旧输入仍保留在本机；可对照当前目录后明确恢复。';}}}}catch{/* Invalid local data never overrides the server catalog. */}if(!fields.value.some(item=>item.id===selected.value))selected.value=fields.value[0]?.id??'';}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function mayLeave(){if(busy.value)return false;remember();return !dirty.value||await app.confirmAction('未保存的字段配置已在此浏览器为当前身份保留，返回后可继续。离开当前页面？',{title:'保留字段配置',confirmLabel:'保留并离开',cancelLabel:'继续编辑'});}
const unregister=app.registerDraftGuard(mayLeave);onBeforeRouteLeave(mayLeave);
function beforeUnload(event:BeforeUnloadEvent){remember();if(dirty.value){event.preventDefault();event.returnValue='';}}
window.addEventListener('beforeunload',beforeUnload);
onBeforeUnmount(()=>{remember();generation++;unregister();window.removeEventListener('beforeunload',beforeUnload);});
watch(fields,remember,{deep:true});
watchCredentialContext(()=>app.status?.identity,()=>{state.value=undefined;fields.value=[];baseline.value='';notice.value='';projects.value=undefined;syncResults.value=undefined;projectSelection.value=[];identities.value=undefined;managerId.value='';busy.value=false;projectLoading.value=false;adding.value=false;history.value=undefined;historical.value=undefined;oldDraft.value=undefined;void load();});
async function restoreOldDraft(){const current=generation;try{if(!oldDraft.value||!await app.confirmAction('将旧输入放入当前目录表单。尚未保存；请核对新增、移除和选项变更后，再明确保存为新版本。',{title:'恢复旧目录输入',confirmLabel:'恢复到表单'})||current!==generation)return;const recovered=cloneGlobalFieldDraft(oldDraft.value);fields.value=recovered;oldDraft.value=undefined;selected.value=recovered[0]?.id??'';remember();}catch(cause){if(current===generation)error.value='无法恢复旧目录输入，原输入仍保留：'+(cause as Error).message;}}
function addField(){if(!state.value?.canEdit||busy.value)return;const id=newId.value.trim();if(!/^[a-z][a-z0-9_-]{0,63}$/.test(id)){error.value='字段 ID 需以小写英文字母开头，使用英文、数字、下划线或短横线，最多64个字符。';return;}if(fields.value.some(item=>item.id===id)){error.value='此字段 ID 已存在。';return;}if(!newName.value.trim()||fields.value.length>=200){error.value='请填写显示名称；全局目录最多200个字段。';return;}fields.value.push({id,displayName:newName.value.trim(),description:'',type:'single',options:[{id:'option_1',displayName:'选项一',color:'#2563EB'}]});selected.value=id;adding.value=false;newId.value='';newName.value='';error.value='';}
async function removeField(){const current=generation,target=field.value;if(!state.value?.canEdit||!target||busy.value)return;if(!await app.confirmAction(`将 ${target.id}（${target.displayName}）退出当前全局目录。新项目不再采用；已采用项目保留定义快照、源值和历史，需项目管理员另行明确删除。新项目或所选提交缺少发布必要维度时会阻止正式发布。`,{title:'移除全局字段',confirmLabel:'从目录移除'})||current!==generation)return;fields.value=fields.value.filter(item=>item!==target);selected.value=fields.value[0]?.id??'';}
async function changeType(value:'single'|'multi',element:HTMLSelectElement){const current=generation,target=field.value;if(!target)return;if(!await app.confirmAction('类型变更只创建新目录版本，不转换已有样本值。项目显式同步时若现有值不符合新类型，将阻止同步；项目采用后若发布必要维度类型不符，会阻止发布。',{title:'更改全局字段类型',confirmLabel:'更改类型'})||current!==generation){element.value=target.type;return;}target.type=value;}
function addOption(){if(!field.value||!state.value?.canEdit)return;const colors=['#2563EB','#DC2626','#059669','#7C3AED','#D97706','#0284C7','#DB2777','#4F46E5'],used=new Set(field.value.options.map(option=>option.color.toUpperCase()));field.value.options.push({id:'',displayName:'',description:'',color:colors.find(color=>!used.has(color))??colors[field.value.options.length%colors.length]!});}
async function removeOption(index:number){const current=generation,target=field.value;if(!target||target.options.length<=1||!state.value?.canEdit)return;const option=target.options[index];if(!option||!await app.confirmAction(`移除选项 ${option.id||'未命名选项'}。历史目录和已采用项目保留原值；项目中仍使用此原值时，新规范同步会被阻止，需另行处理样本。`,{title:'移除字段选项',confirmLabel:'移除选项'})||current!==generation)return;target.options.splice(index,1);}
async function loadIdentities(){const current=generation;try{const result=await request<Array<{id:string;name:string}>>('/governance/identities');if(current===generation)identities.value=result;}catch(cause){if(current===generation)error.value=(cause as Error).message;}}
async function maintain(identityId:string,enabled:boolean){if(!state.value?.canEdit||busy.value||dirty.value)return;const current=generation,name=identities.value?.find(item=>item.id===identityId)?.name??state.value.maintainers.find(item=>item.id===identityId)?.name??'指定人员';if(!await app.confirmAction(`${enabled?'允许':'移除'} ${name} 查看全局字段管理。指定人员只能查看；全局字段写入和批量同步仍仅限实例管理员。该设置不授予项目数据访问权限。`,{title:'字段目录查看权限',confirmLabel:enabled?'允许查看':'移除查看权限'})||current!==generation)return;busy.value=true;error.value='';try{const result=await post<GlobalFieldCatalogState>('/global-fields/maintainers',{identityId,enabled,expectedRevision:state.value.catalog.revision});if(current!==generation)return;state.value=result;managerId.value='';history.value=undefined;notice.value='字段目录查看人员已更新，操作已记录。';}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
const projectId=(project:GlobalFieldProjectStatus)=>project.namespace+'/'+project.repo+'/'+project.ref;
async function loadProjects(){if(projectLoading.value)return;projectLoading.value=true;error.value='';const current=generation;try{const result=await request<{catalogRevision:number;projects:GlobalFieldProjectStatus[]}>('/global-fields/projects');if(current===generation){projects.value=result.projects;projectSelection.value=[];}}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)projectLoading.value=false;}}
async function synchronize(){if(!state.value?.canEdit||busy.value||dirty.value)return;const current=generation,revision=state.value.catalog.revision,targets=(projects.value??[]).filter(project=>projectSelection.value.includes(projectId(project))&&project.needsAdoption&&project.canAdopt);if(!targets.length)return;if(!await app.confirmAction(`为选中的 ${targets.length} 个项目同步活动全局字段定义。每个变化的项目产生一次配置提交；已退出目录的项目字段继续保留。不会转换或删除样本值，类型、选项、任务或草稿冲突会保留并单独报告。`,{title:'同步项目字段规则',confirmLabel:'同步选中项目'})||current!==generation)return;busy.value=true;error.value='';try{const result=await post<GlobalFieldSynchronizationResult>('/global-fields/synchronize',{expectedRevision:revision,targets:targets.map(project=>({namespace:project.namespace,repo:project.repo,ref:project.ref,expectedCommit:project.commitId}))});if(current!==generation)return;syncResults.value=result;await loadProjects();if(current!==generation)return;notice.value=`项目同步完成：${result.results.filter(item=>item.status==='updated').length} 个更新，${result.results.filter(item=>item.status==='blocked').length} 个待处理。`;}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
async function loadHistory(revision?:number){const current=generation;historyLoading.value=true;error.value='';try{if(revision){const result=await request<GlobalFieldCatalog>('/global-fields/history/'+revision);if(current===generation)historical.value=result;}else{const result=await request<{versions:HistoryEntry[]}>('/global-fields/history');if(current===generation)history.value=result.versions;}}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)historyLoading.value=false;}}
async function refresh(){if(await mayLeave()){notice.value='';await load();}}
async function save(){if(!state.value?.canEdit||busy.value)return;const current=generation;if(!await app.confirmAction('保存为新的全局目录版本。新增、移除、类型及选项 ID 变更只影响新项目默认值和后续显式同步；已采用项目、真实样本值和历史发布保持不变。',{title:'发布字段目录新版本',confirmLabel:'保存新版本'})||current!==generation)return;busy.value=true;error.value='';try{const result=await request<GlobalFieldCatalogState>('/global-fields',{method:'PUT',body:JSON.stringify({expectedRevision:state.value.catalog.revision,fields:fields.value})});if(current!==generation)return;state.value=result;fields.value=structuredClone(result.catalog.fields);baseline.value=JSON.stringify(fields.value);oldDraft.value=undefined;remember();projects.value=undefined;projectSelection.value=[];syncResults.value=undefined;history.value=undefined;historical.value=undefined;notice.value='全局目录新版本已保存，历史快照已保留。新项目采用当前目录；现有项目需显式同步。';}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
void load();
</script>
<template>
<section class="field-management">
  <header class="field-management-heading"><div><span class="eyebrow"><Columns3 :size="15"/>数据规范</span><h1>字段管理</h1><p>管理员维护全局字段与选项；项目采用固定快照，标注人员按项目规范选择取值。</p></div><div class="button-row"><button class="btn" :disabled="loading||busy" @click="refresh"><RefreshCw :size="15"/>刷新</button><button v-if="state?.canEdit" class="btn primary" :disabled="!dirty||busy" @click="save"><LoaderCircle v-if="busy" class="spin" :size="15"/><Save v-else :size="15"/>保存全局规则</button></div></header>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="field-management-notice" role="status"><Check :size="16"/>{{notice}}<button v-if="oldDraft&&state?.canEdit" class="btn" @click="restoreOldDraft">恢复旧输入</button></p>
  <div v-if="loading" class="panel empty" role="status"><LoaderCircle class="spin" :size="25"/>正在读取全局字段…</div>
  <div v-else-if="!state?.canManage" class="panel empty"><h2>需要字段目录查看权限</h2><p>仅实例管理员或指定人员可进入字段管理。</p></div>
  <template v-else>
  <p v-if="!state.canEdit" class="field-management-notice"><Info :size="16"/>当前身份只可查看目录。新增、编辑、移除及批量同步由实例管理员执行。</p>
  <div class="field-management-layout">
    <aside class="panel field-management-directory"><h2>活动全局字段 <span>{{fields.length}}</span></h2><button v-for="item in fields" :key="item.id" :class="{selected:selected===item.id}" @click="selected=item.id"><span><code>{{item.id}}</code><strong>{{item.displayName}}</strong></span><small>{{item.type==='multi'?'多选':'单选'}}</small></button><button v-if="state.canEdit" class="btn field-add-button" :disabled="busy||fields.length>=200" @click="adding=!adding"><Plus :size="15"/>新增全局字段</button><form v-if="adding" class="field-management-form field-add-form" @submit.prevent="addField"><label>新字段 ID<input v-model="newId" maxlength="64" placeholder="english_id" required/></label><label>显示名称<input v-model="newName" maxlength="120" required/></label><div class="button-row"><button class="btn primary" :disabled="busy" type="submit">加入目录</button><button class="btn" type="button" @click="adding=false">取消</button></div></form><p><Info :size="14"/>字段 ID 创建后固定，更名请新增字段。目录可为空；移除项不会自动补回。最多200个字段。</p></aside>
    <article v-if="field" class="panel field-management-editor"><fieldset class="field-management-controls" :disabled="busy||!state.canEdit"><header><div><code>{{field.id}}</code><h2>{{field.displayName}}</h2><p>{{semantics[field.id]||'全局选择型样本字段。取值与业务标签、源真值及访问授权分别维护。'}}</p></div><button v-if="state.canEdit" class="btn field-remove-button" @click="removeField"><Trash2 :size="14"/>移除字段</button></header>
      <div class="field-management-form"><label>显示名称<input v-model="field.displayName" maxlength="120"/></label><label>选择类型<select :value="field.type" @change="changeType(($event.target as HTMLSelectElement).value as 'single'|'multi',$event.target as HTMLSelectElement)"><option value="single">单选</option><option value="multi">多选</option></select></label><label>字段说明<textarea v-model="field.description" rows="3" maxlength="4000"/></label></div>
      <div class="panel-header"><div><h3>可选值</h3><p>选项 ID 是保存的原值。改名等同移除旧值、增加新值；不会转换已有样本。</p></div><button class="btn" :disabled="field.options.length>=200" @click="addOption"><Plus :size="14"/>增加选项</button></div>
      <div class="field-options-scroll"><table class="field-options-table"><thead><tr><th>选项 ID</th><th>显示名称</th><th>说明</th><th>颜色</th><th><span class="sr-only">操作</span></th></tr></thead><tbody><tr v-for="(option,index) in field.options" :key="index"><td><input v-model="option.id" :aria-label="'选项 '+(index+1)+' ID'" placeholder="english_id" maxlength="64"/></td><td><input v-model="option.displayName" :aria-label="'选项 '+(index+1)+' 显示名称'" maxlength="120"/></td><td><input v-model="option.description" :aria-label="'选项 '+(index+1)+' 说明'" maxlength="1000" placeholder="可选说明"/></td><td><label class="field-option-color"><input v-model="option.color" type="color" :aria-label="'选项 '+(index+1)+' 颜色'"/><code>{{option.color}}</code></label></td><td><button class="icon-button" :disabled="field.options.length<=1" :aria-label="'删除选项 '+(option.id||index+1)" title="至少保留一个选项" @click="removeOption(index)"><Trash2 :size="15"/></button></td></tr></tbody></table></div>
      <p class="field-management-footnote"><Info :size="15"/>不会自动给样本赋值。隐藏和分享字段不替代访问授权；正式发布检查项目固定提交：所需 split、quality、purposes、visibility 定义缺失或类型不符时会阻止发布。</p>
    </fieldset></article><article v-else class="panel empty"><Columns3 :size="28"/><h2>当前目录没有字段</h2><p>管理员可以新增全局字段。已采用项目继续保留各自快照和原始取值。</p></article>
  </div>
  <section v-if="state.owner" class="panel field-management-adoption"><div class="panel-header"><div><h2>字段目录查看人员</h2><p>实例管理员可编辑。指定人员只能查看，不授予全局写入、项目同步或样本读取权限。</p></div><button v-if="!identities" class="btn" :disabled="busy" @click="loadIdentities">选择查看人员</button></div><div v-if="identities" class="field-maintainer-picker"><label>指定人员<select v-model="managerId" :disabled="busy||dirty"><option value="">选择已有身份</option><option v-for="identity in identities.filter(item=>!state?.maintainers.some(person=>person.id===item.id))" :key="identity.id" :value="identity.id">{{identity.name}}</option></select></label><button class="btn" :disabled="!managerId||busy||dirty" @click="maintain(managerId,true)">允许查看</button></div><ul class="field-maintainer-list"><li v-for="person in state.maintainers" :key="person.id"><span>{{person.name}} · 只读</span><button class="btn" :disabled="busy||dirty" @click="maintain(person.id,false)">移除查看权限</button></li></ul><p v-if="!state.maintainers.length">尚未指定其他查看人员。</p></section>
  <section class="panel field-management-adoption"><div class="panel-header"><div><h2>目录历史</h2><p>每次保存保留完整不可变快照；查看历史不会恢复、覆盖当前目录或改写项目。</p></div><button class="btn" :disabled="historyLoading||busy" @click="loadHistory()"><History :size="14"/>{{historyLoading?'正在读取…':'查看历史版本'}}</button></div><div v-if="history" class="field-history-list"><button v-for="entry in [...history].reverse()" :key="entry.revision" class="btn" :disabled="historyLoading" @click="loadHistory(entry.revision)">r{{entry.revision}} · {{entry.fieldCount}} 个字段 · {{entry.updatedAt?new Date(entry.updatedAt).toLocaleString():'初始目录'}}</button></div><div v-if="historical" class="field-history-snapshot"><h3>r{{historical.revision}} · 只读快照</h3><div class="field-options-scroll"><table class="field-options-table"><thead><tr><th>字段 ID</th><th>显示名称</th><th>类型</th><th>选项 ID</th></tr></thead><tbody><tr v-for="item in historical.fields" :key="item.id"><td><code>{{item.id}}</code></td><td>{{item.displayName}}</td><td>{{item.type==='multi'?'多选':'单选'}}</td><td>{{item.options.map(option=>option.id+'（'+option.displayName+'）').join('、')}}</td></tr><tr v-if="!historical.fields.length"><td colspan="4">该版本目录为空。</td></tr></tbody></table></div></div></section>
  <section class="panel field-management-adoption"><div class="panel-header"><div><h2>项目采用情况</h2><p>同步仅应用活动目录定义。已退出全局的字段保留项目来源快照，项目管理员可在设置中明确删除；不会静默删除源值。</p></div><div class="button-row"><button class="btn" :disabled="projectLoading||busy||dirty" @click="loadProjects"><RefreshCw :size="14"/>{{projectLoading?'正在核对…':'核对现有项目'}}</button><button v-if="state.canEdit" class="btn primary" :disabled="!projectSelection.length||busy||dirty" @click="synchronize">同步选中项目</button></div></div><p v-if="dirty" class="field-management-footnote">请先保存全局规则，再核对项目采用情况。</p><div v-if="projects" class="field-options-scroll"><table class="field-options-table"><thead><tr><th>选择</th><th>项目 / 分支</th><th>待同步字段 / 已退出目录</th><th>状态</th></tr></thead><tbody><tr v-for="project in projects" :key="projectId(project)"><td><input v-model="projectSelection" type="checkbox" :value="projectId(project)" :disabled="!state.canEdit||!project.canAdopt||!project.needsAdoption||busy" :aria-label="'同步 '+project.namespace+'/'+project.repo"/></td><td><RouterLink :to="`/repos/${encodeURIComponent(project.namespace)}/${encodeURIComponent(project.repo)}/settings`">{{project.namespace}}/{{project.repo}}</RouterLink><small class="field-project-branch">{{project.ref}}</small></td><td>{{[...project.missing,...project.changed].join('、')||'—'}}<small v-if="project.retired.length" class="field-project-branch">已退出全局，项目保留：{{project.retired.join('、')}}</small></td><td>{{!project.canAdopt?'无项目维护权限':project.needsAdoption?'待同步':'已采用当前活动规则'}}</td></tr><tr v-if="!projects.length"><td colspan="4">没有可核对的已配置数据集。</td></tr></tbody></table></div><div v-if="syncResults?.results.some(item=>item.status==='blocked')" class="field-sync-blocked" role="status"><p v-for="result in syncResults.results.filter(item=>item.status==='blocked')" :key="result.namespace+'/'+result.repo">{{result.namespace}}/{{result.repo}}：未变更（{{result.code}}）。处理该项目的草稿、任务或原值规则冲突后可重试。</p></div></section>
  </template>
</section>
</template>
